/* Standalone design prototype. No application ledger, storage or cloud code is loaded. */
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₹'+Number(n).toLocaleString('en-IN',{maximumFractionDigits:2}),signed=n=>(n>=0?'+':'−')+money(Math.abs(n));
const paths={settings:'M4 7h16M4 17h16M8 4v6m8 4v6',back:'m14 5-7 7 7 7',arrow:'M4 12h16m-6-6 6 6-6 6',home:'M3 10 12 3l9 7v10H3Zm6 10v-7h6v7',table:'M7 5h10a4 4 0 0 1 4 4v6a4 4 0 0 1-4 4H7a4 4 0 0 1-4-4V9a4 4 0 0 1 4-4ZM7 9h10M7 13h5',players:'M15 20v-3a6 6 0 0 0-12 0v3m15-7a5 5 0 0 1 3 5v2M9 10a3 3 0 1 0 0-6 3 3 0 0 0 0 6Zm8-6a3 3 0 0 1 0 6',history:'M3 11a9 9 0 1 1 2 7M3 4v7h7m2-4v6l4 2',chart:'M4 20h16M7 15V9m5 6V4m5 11V8',check:'m5 12 4 4L19 6',clock:'M12 7v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6Z',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',cup:'M7 3h10v7a5 5 0 0 1-10 0Zm0 2H3v4a5 5 0 0 0 5 5M17 5h4v4a5 5 0 0 1-5 5M12 15v6m-5 0h10',more:'M5 12h.01M12 12h.01M19 12h.01',plus:'M12 4v16M4 12h16',receipt:'M5 3h14v18l-3-2-4 2-4-2-3 2ZM8 7h8M8 11h8M8 15h4'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.arrow}" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const link=(text,route,cls='')=>`<a class="button ${cls}" href="#${route}">${text}</a>`;
const button=(text,action,cls='',attrs='')=>`<button type="button" class="button ${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const head=(title,subtitle='',back='home')=>`${back?`<a class="back" href="#${back}">${icon('back')}${back==='home'?'Home':back==='table'?'Table':back==='tournament'?'Tournament':'Back'}</a>`:''}<header class="page-heading"><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</header>`;
const avatar=p=>`<span class="avatar">${esc(p.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span>`;
const identity=(p,sub='')=>`<div class="identity">${avatar(p)}<div class="grow"><div class="name">${esc(p.name)}</div>${sub?`<small>${sub}</small>`:''}</div></div>`;
const detail=(label,value,cls='')=>`<div class="detail ${cls}"><span>${label}</span><strong>${value}</strong></div>`;
const notice=(text,cls='')=>`<div class="notice ${cls}">${text}</div>`;
let toastTimer;function toast(t,success=false){if(window.CashMotionLibrary)CashMotionLibrary.announce(t,success);else $('#toast').textContent=t;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',4000)}
const contacts=['Alex Morgan','Jamie Chen','Sam Rivera','Taylor Reed','Jordan Patel','Casey Brooks','Morgan Lee','Riley Shah','Avery Singh','Quinn Parker','Drew Wilson','Cameron Ali','Skyler Kim','Robin Das','Charlie Evans'].map((name,i)=>({id:i+1,name,last:5000}));
const now=Date.now();let minimumHours=3,tableName='Friday Night',tableClosed=false,filter='all',profileId=1,receiptId='jamie',receiptBack='settlement',transferPaid=false,restored=false,editPlayerId=null;
let players=contacts.slice(0,3).map((p,i)=>({...p,buy:5000,out:null,received:5000,firstBuy:now-[40,10,190][i]*60000,minimum:180*60000}));
let amountDraft={kind:'buy',id:4,amount:'',received:'',reason:''},cashDraft={id:1,amount:'',override:false};
let tx=[{name:'Alex Morgan',time:'19:30',title:'Initial buy-in',amount:5000},{name:'Jamie Chen',time:'20:00',title:'Initial buy-in',amount:5000},{name:'Sam Rivera',time:'17:00',title:'Initial buy-in',amount:5000}];
const receiptPlayers={jamie:{name:'Jamie Chen',buy:9000,out:11200,received:9000,paid:5000,entries:[['19:00 · Buy-in',5000],['20:10 · Rebuy',2000],['21:05 · Rebuy',2000]]},alex:{name:'Alex Morgan',buy:5000,out:3000,received:5000,paid:0,entries:[['19:30 · Buy-in',5000]]},sam:{name:'Sam Rivera',buy:5000,out:3000,received:0,paid:0,entries:[['18:00 · Buy-in',5000]]},jordan:{name:'Jordan Patel',buy:5000,out:0,received:5000,paid:0,entries:[['20:00 · Buy-in',5000]]}};
const groups={
'Home & cash tables':[['home','Home'],['new-table','Create cash table'],['table','Running table'],['table-settings','Table settings'],['add-player','Add player to table']],
'Money & safeguards':[['buy-in','Buy-in / rebuy'],['amount-review','Review buy-in'],['cash-out','Enter cash-out'],['cash-out-review','Review cash-out'],['early-exit','Early-profit warning'],['correction','Correct recorded amount'],['review','Review & close table'],['activity','Transaction activity']],
'Players & history':[['players','Saved players'],['new-player','New / edit player'],['player','Player profile'],['history','Past tables'],['history-detail','Past table results'],['insights','Game-night insights']],
'Settlement & receipts':[['settlement','Who pays whom'],['payment','Record a payment'],['payments','Payments & corrections'],['receipt','Player receipt']],
'One-table tournament':[['tournament-setup','Start tournament'],['tournament-structure','Blind structure'],['tournament','Live tournament'],['tournament-players','Entrants & seats'],['tournament-entry','Entry / rebuy / add-on'],['tournament-elimination','Record elimination'],['tournament-payouts','Prize pool & payouts'],['tournament-results','Final standings']],
'Settings & recovery':[['settings','Settings'],['cloud','Cloud backup'],['restore','Choose restore file'],['restore-review','Review restore'],['install','Install app'],['privacy','Privacy & recovery']],
'Design system':[['components','Reusable components']]};
const routeMeta=Object.entries(groups).flatMap(([group,rs])=>rs.map(([id,label])=>({id,label,group})));
const contexts={home:'The starting point for cash games and tournaments. Both actions are visible before scrolling.',table:'Call-time badges sit beside names. Each deadline uses that player’s own first confirmed buy-in. The default minimum is 3 hours.',receipt:'Profit or loss is distinct from remaining payment. Switch between real player identities to inspect all receipt outcomes.', 'early-exit':'Early profitable exits are advisory, with a house-exception path into the normal final review. No forced payout.',insights:'Phase-2 presentation and required collection fields. Completed sessions, source values and timing completeness stay explicit.',cloud:'Production-facing connection flow; live provider setup remains an implementation/release gate.'};
let currentRoute='home',activeInfo=false;function go(route){if(location.hash==='#'+route)render();else location.hash=route}
function person(){return players.find(p=>p.id===cashDraft.id)||players[0]}
function balance(){const buy=players.reduce((s,p)=>s+p.buy,0),out=players.reduce((s,p)=>s+(p.out||0),0),pending=players.filter(p=>p.out===null);return{buy,out,pending,difference:buy-out-300}}
const chipArt=`<svg class="hero-art" viewBox="0 0 120 120" aria-hidden="true"><g fill="none" stroke="currentColor"><circle cx="60" cy="60" r="54"/><circle cx="60" cy="60" r="42"/><circle cx="60" cy="60" r="32"/><path d="M60 6v13m0 82v13M6 60h13m82 0h13M22 22l9 9m58 58 9 9M22 98l9-9m58-58 9-9"/></g></svg>`;
function hero(label,value,footer=''){return `<section class="hero">${chipArt}<span class="eyebrow">${label}</span><div class="amount">${value}</div>${footer}</section>`}
function clockFor(p){const left=Math.max(0,Math.ceil((p.firstBuy+p.minimum-Date.now())/1000));return{left,met:left===0,text:String(Math.floor(left/3600)).padStart(2,'0')+':'+String(Math.floor(left%3600/60)).padStart(2,'0')+':'+String(left%60).padStart(2,'0')}}
function playerCard(p){const c=clockFor(p);return `<article class="player"><div class="row start">${identity(p,p.out===null?'Playing · result pending':'Cashed out')}<div class="clock ${c.met?'met':''}" data-clock="${p.id}"><strong>${c.text}</strong><small>${c.met?'Eligible to leave':'Call time pending'}</small></div></div><div class="player-money"><small>Total buy-in</small><strong class="blue">${money(p.buy)}</strong></div>${p.out!==null?detail('Poker result',`<span class="${p.out-p.buy>=0?'positive':'negative'}">${signed(p.out-p.buy)}</span>`):''}<div class="player-actions">${p.out===null?button('+ Add money','rebuy','compact',`data-id="${p.id}"`):button('Return to play','reentry','compact',`data-id="${p.id}"`)}${button(p.out===null?'Cash out':'Edit cash-out','cashout','compact',`data-id="${p.id}"`)}</div><div class="row">${button('Payments','player-payments','text compact',`data-id="${p.id}"`)}${button('More','player-options','text compact',`data-id="${p.id}"`)}</div></article>`}
function home(){return head('Your tables','A place for every game.','')+`<div class="two">${link(icon('plus')+'Create cash table','new-table','primary')}${link(icon('cup')+'Start tournament','tournament-setup')}</div><div class="section-head"><h2>Running now</h2><span class="tag good">Private</span></div><section class="card"><div class="row"><span class="tag">Cash game</span><small>Today</small></div><h2 style="margin-top:13px">${esc(tableName)}</h2><p class="small">${players.length} players · ${players.filter(p=>p.out===null).length} playing</p><div class="amount medium">${money(balance().buy)}</div>${link('Open table '+icon('arrow'),'table','primary w-full')}</section><div class="section-head"><h2>Recent tables</h2>${link('View all','history','text compact')}</div>${historyCard('Friday Regulars','6 Nov 2026','9 players · ₹90,000 buy-ins','₹6,200 outstanding')}<div class="notice">${icon('shield')}<span>Your table stays private. Share only the receipts and summaries you choose.</span></div>`}
function newTable(){return head('Create a cash table','Private by default.')+`<form data-form="new-table"><div class="field"><label for="table-name">Table name</label><input id="table-name" maxlength="60" placeholder="Friday Night" required></div><div class="field"><label for="banker">Banker</label><select id="banker"><option>You · host</option>${contacts.map(p=>`<option>${p.name}</option>`).join('')}</select></div><div class="field"><label for="minimum-new">Minimum play · hours</label><input id="minimum-new" type="number" min="0" max="24" step="0.25" value="3" required><p class="small">Each player starts their own clock when their buy-in is confirmed.</p></div>${notice('The current table must be closed and balanced before a new cash table starts. Completed tables and unpaid balances stay in history.')}<div class="actions"><button class="button primary" type="submit">Create private table</button></div></form>`}
function table(){let list=players.filter(p=>filter==='playing'?p.out===null:filter==='cashed'?p.out!==null:filter==='outstanding'?p.out>0: true);return head(esc(tableName),'Private · You’re banking','home')+hero('Total buy-in',money(balance().buy),`<div class="row"><small>${players.filter(p=>p.out===null).length} playing</small><a class="small positive" href="#table-settings">Minimum play · ${minimumHours}h</a></div>`)+`<div class="section-head"><h2>At the table</h2>${link('+ Add player','add-player','text compact')}</div><div class="pills" aria-label="Filter players">${[['all','All'],['playing','Playing'],['cashed','Cashed out'],['outstanding','Payment due']].map(([id,l])=>`<button class="pill ${filter===id?'selected':''}" data-action="filter" data-value="${id}" aria-pressed="${filter===id}">${l}</button>`).join('')}</div><div class="stack">${list.map(playerCard).join('')||notice('No players match this filter.')}</div><div class="section-head"><h3>Rake · ₹300</h3>${button('+ Add rake','rake','text compact')}</div><div class="row">${link('Table settings','table-settings','text')}${link('Activity','activity','text')}</div><div class="actions">${link('Review & end table','review','primary')}</div><p class="hint">${balance().pending.length} cash-outs pending. Stacks and actual payouts are recorded separately.</p>`}
function tableSettings(){return head('Table settings',esc(tableName),'table')+`<form data-form="table-settings"><div class="field"><label for="minimum-hours">Minimum play · hours</label><input id="minimum-hours" type="number" min="0" max="24" step="0.25" value="${minimumHours}" required></div><p class="small">Default: 3 hours. Zero disables the rule for new buy-ins.</p>${notice('Each player has an independent clock. Rebuys do not restart it. Before call time, profitable exits require a house-exception confirmation.')}${notice('Changes apply to new buy-ins. Existing players keep their recorded minimum and start time.')}<div class="two"><div class="field"><label for="small-blind">Small blind · ₹</label><input id="small-blind" type="number" min="1" value="50" required></div><div class="field"><label for="big-blind">Big blind · ₹</label><input id="big-blind" type="number" min="1" value="100" required></div></div><p class="small">Stakes describe the game. Buy-ins and cash-outs remain cash amounts.</p><div class="actions"><button class="button primary" type="submit">Save settings</button></div></form>`}
function roster(seating=false){return head(seating?'Add a player':'Your players',seating?'Search saved players by name or phone.':'Familiar faces. A fresh table.',seating?'table':'home')+`<label for="player-search" class="small">Search saved players</label><input id="player-search" type="search" placeholder="Name or phone"><div id="roster-results" style="margin-top:15px">${rosterRows('',seating)}</div><div class="actions">${link('+ Create new player','new-player','primary')}</div>`}
function rosterRows(query='',seating=false){const list=contacts.filter(p=>!p.archived&&p.name.toLowerCase().includes(query.toLowerCase()));return list.map(p=>`<div class="list-row">${avatar(p)}<div class="grow"><strong>${p.name}</strong><small>${p.phone||'No phone number added'}</small></div>${seating?players.some(x=>x.id===p.id)?'<span class="tag">Seated</span>':button('Add','seat','compact',`data-id="${p.id}"`):button(icon('arrow'),'profile','compact',`data-id="${p.id}" aria-label="Open ${p.name}"`)}</div>`).join('')||notice('No matching players. Try another name.')}
function playerForm(){const editing=contacts.find(p=>p.id===editPlayerId);return head(editing?'Edit player':'New player','Saved only to your private records.','players')+`<form data-form="player"><div class="field"><label for="player-name">Name</label><input id="player-name" maxlength="60" required value="${esc(editing?.name||'')}"></div><div class="field"><label for="player-phone">Phone number · optional</label><input id="player-phone" type="tel" maxlength="60" value="${esc(editing?.phone||'')}"></div><div class="field"><label for="player-photo">Photo · optional</label><input id="player-photo" type="file" accept="image/png,image/jpeg,image/webp"></div>${notice('Similar names and phone numbers are checked before creating a duplicate. Player identity stays stable if their details change.')}<div class="actions"><button class="button primary" type="submit">Save player</button></div></form>`}
const profileSessions=[4800,-3000,8200,-5600,3800,2600,-4200,6200,-3600,3200].map((net,i)=>({net,date:['09 Oct','12 Oct','15 Oct','18 Oct','21 Oct','24 Oct','27 Oct','30 Oct','03 Nov','06 Nov'][i],name:['Friday Regulars','Midweek Mix','After Hours','Sunday Session','Saturday Regulars'][i%5]}));
let profileTab='overview',profileSession=9;
function statCard(label,value,caption,tone=''){return `<section class="stat spectrum-stat"><div class="stat-label">${label}</div><strong class="${tone}">${value}</strong><small>${caption}</small></section>`}
function profileTabs(key='Player profile'){return `<div class="segment profile-segment" aria-label="${key}">${['overview','sessions'].map(t=>`<button class="${profileTab===t?'selected':''}" data-action="profile-tab" data-value="${t}" aria-pressed="${profileTab===t}">${t==='overview'?'Overview':'Sessions'}${t==='sessions'?'<span class="tab-count">10</span>':''}</button>`).join('')}</div>`}
function profileTrend(){let running=0;const totals=profileSessions.map(s=>running+=s.net),points=totals.map((v,i)=>`${12+i*34},${112-v/14000*90}`),selected=profileSessions[profileSession];return `<section class="card profile-trend"><div class="row"><div><h3>Result over time</h3><small>Completed cash sessions</small></div><span class="tag">10 sessions</span></div><svg class="chart" viewBox="0 0 330 130" role="img" aria-label="Cumulative results across ten completed sessions, from positive 4,800 to positive 12,400 rupees"><path class="grid" d="M12 112H318M12 67H318M12 22H318"/><path d="M12 112 ${points.map(p=>'L'+p).join(' ')} L318 112Z" fill="var(--ambient)"/><path class="line" d="M${points.join(' L')}"/><circle cx="${12+profileSession*34}" cy="${112-totals[profileSession]/14000*90}" r="5" fill="var(--green)" stroke="var(--surface)" stroke-width="3"/></svg><div class="row"><small>09 Oct</small><small>06 Nov</small></div><label for="session-inspector" class="sr-only">Inspect completed session</label><input id="session-inspector" class="session-slider" type="range" min="0" max="9" step="1" value="${profileSession}" aria-valuetext="${selected.date}, session result ${signed(selected.net)}, cumulative ${signed(totals[profileSession])}"><div class="session-readout" id="session-readout" aria-live="polite"><div><strong>${selected.date} · ${selected.name}</strong><small>Session ${profileSession+1} of 10</small></div><div class="readout-money"><strong class="${selected.net>=0?'positive':'negative'}">${signed(selected.net)}</strong><small>${signed(totals[profileSession])} cumulative</small></div></div><p class="small chart-hint">Drag or use the arrow keys to inspect a session.</p></section>`}
function profileSessionRows(){return `<div class="session-list">${[...profileSessions].reverse().map((s,i)=>`<a class="list-row" href="#history-detail"><span class="session-mark ${s.net>=0?'win':'loss'}" aria-hidden="true">${s.net>=0?'↗':'↘'}</span><div class="grow"><strong>${s.name}</strong><small>${s.date} 2026 · cash game</small></div><div class="session-result"><strong class="${s.net>=0?'positive':'negative'}">${signed(s.net)}</strong><small>${s.net>=0?'Won':'Lost'}</small></div></a>`).join('')}</div>`}
function profile(){const p=contacts.find(p=>p.id===profileId)||contacts[0],seated=players.some(x=>x.id===p.id);return head('Player profile','','players')+`<div class="profile-identity"><div class="identity"><span class="avatar large">${esc(p.name.split(' ').map(n=>n[0]).join(''))}</span><div><span class="eyebrow">Your roster</span><h2>${esc(p.name)}</h2><small>${esc(p.phone||'Phone number not added')}</small></div></div>${button(icon('settings'),'edit-player','compact',`data-id="${p.id}" aria-label="Edit ${esc(p.name)}"`)}</div><section class="profile-result magic-card"><div class="row"><span class="eyebrow">Net poker result</span><span class="result-seal">${icon('check')} Completed sessions</span></div><div class="amount positive">+₹12,400</div><p class="small">Across 10 cash-game sessions</p><div class="profile-summary"><div><strong>10</strong><small>Sessions</small></div><div><strong>60%</strong><small>Win rate</small></div><div><strong>6 <span>/ 4</span></strong><small>Wins / losses</small></div></div></section>${profileTabs()}${profileTab==='overview'?`${profileTrend()}<div class="section-head"><h2>By the numbers</h2></div><div class="two stats-grid">${statCard('Average win','+₹4,800','6 winning sessions','positive')}${statCard('Average loss','−₹4,100','4 losing sessions','negative')}${statCard('Biggest win','+₹8,200','15 Oct · After Hours','positive')}${statCard('Biggest loss','−₹5,600','18 Oct · Sunday Session','negative')}</div><div class="card profile-buyin">${detail('Average buy-in','₹10,000')}${detail('Total buy-ins','₹1,00,000')}<small>Includes initial buy-ins and rebuys per session.</small></div><p class="small profile-footnote">Win/loss averages use matching sessions only. Live stacks and payment timing do not change poker results.</p>`:`<div class="row section-head"><h2>Completed sessions</h2><span class="tag">Latest first</span></div>${profileSessionRows()}`}
<div class="actions">${seated?'<button class="button primary" disabled>Already at this table</button>':button('+ Add to table','seat','primary',`data-id="${p.id}"`)}</div><details class="player-options"><summary>Player options</summary><div class="stack">${button('Edit player','edit-player','',`data-id="${p.id}"`)}${button('Archive player','archive','danger',`data-id="${p.id}"`)}</div><p class="small">Archiving keeps current seats, past results and payment records.</p></details>`}

function amountPage(){const p=contacts.find(p=>p.id===amountDraft.id)||contacts[3],edit=amountDraft.kind==='correction';return head(edit?'Correct buy-in':amountDraft.kind==='rebuy'?'Add money':amountDraft.kind==='reentry'?'Return to play':'Initial buy-in',esc(p.name),'table')+identity(p,edit?'Actual payments remain unchanged.':'Review the amount before recording.')+`<form data-form="amount"><div class="field"><label for="amount">${edit?'Corrected buy-in total':'Cash amount'} · ₹</label><input class="number-input" id="amount" inputmode="decimal" type="text" autocomplete="off" value="${esc(amountDraft.amount)}" placeholder="0" required></div><div class="shortcut">${button('+ '+money(p.last),'shortcut','compact',`data-value="${p.last}"`)}${button('+ ₹1,000','shortcut','compact','data-value="1000"')}${button('Clear','clear','compact')}</div>${keypad()}${edit?`<div class="field"><label for="reason">Reason for correction</label><input id="reason" minlength="3" maxlength="160" required value="${esc(amountDraft.reason)}"></div>`:`<fieldset class="field"><legend>Has this money been received?</legend><label class="check"><input type="radio" name="received" value="yes" ${amountDraft.received==='yes'?'checked':''} required> Received now</label><label class="check"><input type="radio" name="received" value="no" ${amountDraft.received==='no'?'checked':''}> Not yet · track as due</label></fieldset>`}<p id="amount-error" class="negative small" role="alert"></p><div class="actions"><button class="button primary" type="submit">Review amount</button></div><p class="hint">Shortcut taps add to this draft. Nothing is recorded yet.</p></form>`}
function keypad(){return `<div class="keypad" aria-label="Cash amount keypad">${['1','2','3','4','5','6','7','8','9','.','0','⌫'].map(k=>button(k,'key','',`data-value="${k}" aria-label="${k==='⌫'?'Backspace':k==='.'?'Decimal point':k}"`)).join('')}</div>`}
function amountReview(){const p=players.find(p=>p.id===amountDraft.id),n=Number(amountDraft.amount)||2000,total=amountDraft.kind==='correction'?n:(p?.buy||0)+n;return head('Check before recording',esc((p||contacts.find(p=>p.id===amountDraft.id))?.name||'Taylor Reed'),'buy-in')+hero(amountDraft.kind==='correction'?'Corrected buy-in total':'Additional buy-in',money(n))+`<section class="card" style="margin-top:16px">${detail('Table',esc(tableName))}${detail('Recorded so far',money(p?.buy||0))}${detail('After this entry',money(total))}${detail('Payment',amountDraft.kind==='correction'?'Unchanged':amountDraft.received==='no'?'Not received · due':'Received now')}${amountDraft.kind==='correction'?detail('Correction reason',esc(amountDraft.reason)):''}</section>${notice(amountDraft.kind==='buy'?'Confirming this buy-in starts this player’s own 3-hour call-time clock.':'The original call-time clock is preserved.')}<div class="actions">${button('Confirm '+money(n),'confirm-amount','primary')}${link('Edit amount','buy-in')}</div>`}
function cashout(){const p=person();return head(p.out===null?'Cash out':'Correct cash-out',esc(p.name),'table')+identity(p,`Total buy-in ${money(p.buy)}`)+`<form data-form="cashout"><div class="field"><label for="cash-stack">Remaining stack · ₹</label><input class="number-input" id="cash-stack" inputmode="decimal" type="text" placeholder="0" value="${esc(cashDraft.amount)}" required></div>${keypad()}${notice('Enter the whole remaining stack, not the profit. Zero is a valid stack. Recording it does not mark money as paid.')}<p class="negative small" id="cash-error" role="alert"></p><div class="actions"><button class="button primary" type="submit">Review cash-out</button></div></form>`}
function cashReview(early=false){const p=person(),n=Number(cashDraft.amount)||0,c=clockFor(p),net=(p.priorOut||0)+n-p.buy;if(early)return cashReview(false)+`<dialog id="early-exit-dialog" class="product-modal" aria-labelledby="early-exit-title"><div class="eyebrow negative">Call time pending</div><h2 id="early-exit-title">Leaving early in profit?</h2><p>${esc(p.name)} has not completed the minimum play time.</p><section class="card" style="margin-top:18px">${detail('Time remaining',c.text)}${detail('Minimum play','3 hours')}${detail('Proposed cash-out',money(n))}${detail('Poker result',signed(net))}</section>${notice('You can make an exception for this house game. The acknowledgement stays in the activity history.')}<div class="actions">${link('Keep playing','table','primary')}${button('Cash out anyway · house exception','allow-early')}</div><p class="hint">Next: final review. No automatic payout.</p></dialog>`;return head('Confirm cash-out',esc(p.name),'cash-out')+hero('Stack to cash out',money(n))+`<section class="card" style="margin-top:16px">${detail('Total buy-ins',money(p.buy))}${detail('Poker result',`<span class="${net>=0?'positive':'negative'}">${signed(net)}</span>`)}${detail('Call time',cashDraft.override?'House exception acknowledged':c.met?'Minimum met':net<=0?'Early exit · no profit':c.text)}</section>${notice('This records the stack only. Actual payout remains separate.')}<div class="actions">${button('Confirm cash-out','confirm-cashout','primary')}${link('Edit stack','cash-out')}</div>`}
function activity(){return head('Table activity','Every confirmed change stays traceable.','table')+`<div class="timeline">${tx.map(t=>`<div class="timeline-item"><strong>${esc(t.title)}</strong><p>${esc(t.name)} · ${money(t.amount)}</p><small>${t.time} · ${esc(tableName)} · INR</small></div>`).join('')}</div>${notice('Corrections retain the earlier entry, a reason and the table’s settings at that point in time.')}`}
function review(){const b=balance();return head('One final check','Every stack. Every chip.','table')+notice(b.pending.length?`${b.pending.length} players still need a cash-out.`:b.difference?'The table does not balance yet.':'All stacks balance.',b.pending.length||b.difference?'warn':'good')+`<section class="card">${detail('Player buy-ins',money(b.buy))}${detail('Cash-out stacks',money(b.out))}${detail('Rake','₹300')}${detail('Difference',money(b.difference),'total')}</section><div class="section-head"><h2>Cash-out stacks</h2></div>${players.map(p=>`<div class="list-row">${identity(p,p.out===null?'Stack not entered':money(p.out))}${button(p.out===null?'Enter stack':'Edit','cashout','compact',`data-id="${p.id}"`)}</div>`).join('')}<div class="actions"><button class="button primary" data-action="close-table" ${b.pending.length||b.difference?'disabled':''}>Confirm table & settle</button>${link('Review activity','activity')}</div><p class="hint">A table can close only when all stacks, including zeroes, are entered and balance with rake.</p>`}
function historyCard(name,date,sub,tail){return `<a class="card" style="display:block;margin-top:12px" href="#history-detail"><div class="row"><span class="tag good">Balanced</span><small>${date}</small></div><h3 style="margin-top:12px">${name}</h3><p class="small" style="margin:6px 0 10px">${sub}</p><div class="row"><strong style="font-size:13px">${tail}</strong>${icon('arrow')}</div></a>`}
function historyPage(){return head('Table history','10 completed tables','home')+`<div class="pills"><span class="pill selected">Cash games</span><a class="pill" href="#tournament-results">Tournaments</a></div>`+['Friday Regulars','Midweek Mix','After Hours','Sunday Session','Saturday Regulars','Friday Night','After Hours II','Sunday Session II','Midweek Mix II','Saturday Regulars II'].map((name,i)=>historyCard(name,`${6-i*3>0?6-i*3:30-i} ${i<2?'Nov':'Oct'} 2026`,'9 players · ₹90,000 buy-ins',i===0?'₹6,200 outstanding':'All payments recorded')).join('')}
function historyDetail(){return head('Friday Regulars','6 Nov 2026 · completed cash table','history')+notice('All 9 stacks entered. Buy-ins = cash-outs + rake.','good')+`<section class="card">${detail('Buy-ins','₹90,000')}${detail('Cash-outs','₹88,200')}${detail('Rake','₹1,800')}</section><div class="section-head"><h2>Final results</h2></div>${[['Jamie Chen','+₹2,200'],['Alex Morgan','−₹2,000'],['Sam Rivera','−₹2,000'],['Jordan Patel','−₹5,000']].map(([n,v])=>`<div class="list-row"><div class="grow"><strong>${n}</strong></div><strong class="${v[0]==='+'?'positive':'negative'}">${v}</strong></div>`).join('')}<p class="small">4 of 9 players shown</p><div class="actions">${link('Results & settlement','settlement','primary')}${link('Player receipts','receipt')}${button('Export transaction CSV','export-csv')}</div>`}
function trend(){return `<section class="card" style="margin:16px 0"><div class="row"><h3>Cumulative result</h3><small>10 sessions</small></div><svg class="chart" viewBox="0 0 350 125" role="img" aria-label="Cumulative result over ten sessions, ending at positive 12,400 rupees"><path class="grid" d="M0 100H350M0 55H350"/><path class="line" d="M0 110 35 80 70 99 105 48 140 83 175 59 210 42 245 69 280 29 315 52 350 31"/></svg><div class="row"><small>First session</small><small>Latest</small></div></section>`}
function insights(){return head('Your game nights','10 completed cash games · 15 players','home')+`<section class="hero"><div class="eyebrow">Total table buy-ins</div><div class="amount">₹9.2 lakh</div><small>Across 10 sessions<br>Includes all rebuys.</small><svg class="fun-art" viewBox="0 0 110 100" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="1.7"><ellipse cx="30" cy="48" rx="18" ry="7"/><path d="M12 48v35c0 9 36 9 36 0V48M12 61c0 9 36 9 36 0M12 73c0 9 36 9 36 0"/><ellipse cx="79" cy="19" rx="18" ry="7"/><path d="M61 19v64c0 9 36 9 36 0V19M61 34c0 9 36 9 36 0M61 49c0 9 36 9 36 0M61 64c0 9 36 9 36 0"/><path d="m28 10 2-6 2 6 6 2-6 2-2 6-2-6-6-2Z"/></g></svg></section><div class="two" style="margin:15px 0"><div class="stat"><small>Average duration</small><strong>4h 20m</strong><small>8 of 10 timed</small></div><div class="stat"><small>Total rake</small><strong>₹18,400</strong><small>10 sessions</small></div></div><section class="card"><h3>Session buy-ins</h3><div class="bars" role="img" aria-label="Buy-ins in thousands: 70, 85, 60, 110, 95, 120, 80, 90, 110, 100">${[58,71,50,92,79,100,67,75,92,83].map(v=>`<i style="--v:${v}%"></i>`).join('')}</div><div class="row"><small>First game</small><small>Latest · ₹ thousands</small></div><details><summary>View source values</summary><p class="small">₹70k, 85k, 60k, 110k, 95k, 120k, 80k, 90k, 110k, 100k. Total ₹920k.</p></details></section>${notice('Duration uses actual recorded play intervals. Missing times are excluded. Cash-game and tournament statistics stay separate.')}<div class="section-head"><h2>Player insights</h2>${link('All players','players','text')}</div>${button('Jamie Chen · 10 sessions','profile','w-full','data-id="2"')}<div class="actions">${button('Import transaction CSV','csv-import')}${button('Export source data','export-csv')}</div>`}
function settlement(){return head('Table settlement','Friday Regulars · balanced stacks','history-detail')+hero('Player payments remaining',money(activeTransferAmount),`<small>${transferPaid?'All player payments recorded':'1 transfer · recorded payments excluded'}</small>`)+`<div class="segment" aria-label="Settlement method"><button class="selected" data-action="bank-mode" aria-pressed="true">Through banker</button><button data-action="direct-mode" aria-pressed="false">Smart direct</button></div>${transferPaid?notice('All player payments recorded.','good'):`<section class="card"><div class="row"><strong>Banker → Jamie Chen</strong><span class="tag warn">Unpaid</span></div><div class="amount medium">${money(activeTransferAmount)}</div>${link('Record paid','payment','primary w-full')}</section>`}<div class="list-row"><div class="grow"><strong>Rake · ₹1,800</strong><small>Distributed outside the app</small></div></div><div class="actions">${link('Recorded payments & corrections','payments')}${link('Player receipts','receipt')}${button('Share table summary','share-summary')}</div><p class="hint">Record payments after money changes hands. The app does not transfer money.</p>`}
function payment(){return head('Record payment','Banker → Jamie Chen','settlement')+hero('Amount remaining',money(activeTransferAmount))+`<form data-form="payment"><div class="field"><label for="payment-amount">Amount paid · ₹</label><input id="payment-amount" inputmode="decimal" value="${activeTransferAmount}" required></div>${notice('Confirm only after the money has changed hands. Partial payments leave the rest outstanding.')}<label class="check"><input type="checkbox" required> I confirm this money was paid.</label><div class="actions"><button class="button primary" type="submit">Confirm payment recorded</button></div></form>`}
function paymentsPage(){return head('Recorded payments','Corrections stay in the history.','settlement')+`<div class="list-row"><div class="grow"><strong>Banker → Jamie Chen</strong><small>₹5,000 · 6 Nov, 22:15</small></div><span class="tag good">Recorded</span></div>${transferPaid?'<div class="list-row"><div class="grow"><strong>Banker → Jamie Chen</strong><small>₹6,200 · 6 Nov, 23:18</small></div><span class="tag good">Recorded</span></div>':''}${notice('Reverse a record only if it was entered incorrectly. Reversal does not move money back.')}<form data-form="reverse"><div class="field"><label for="reverse-reason">Reason to reverse the ₹5,000 record</label><input id="reverse-reason" minlength="3" maxlength="160" required placeholder="Marked paid by mistake"></div><div class="actions"><button class="button danger" type="submit">Review record reversal</button></div></form>`}
function receipt(){const p=receiptPlayers[receiptId],net=p.out-p.buy,due=p.buy-p.received-p.out+p.paid;return head('Player receipt','Friday Regulars · 6 Nov 2026',receiptBack)+`<label for="receipt-player">Player</label><select id="receipt-player">${Object.entries(receiptPlayers).map(([id,p])=>`<option value="${id}" ${id===receiptId?'selected':''}>${p.name}</option>`).join('')}</select><section class="receipt" aria-label="Receipt for ${p.name}"><img class="receipt-logo" src="../wireframes/assets/brand/cash-out-wordmark-light.svg" alt="Cash Out"><div class="receipt-kicker">PLAYER RECEIPT</div><div class="receipt-rule"></div><strong>${p.name}</strong><div class="receipt-muted">Friday Regulars · 6 Nov 2026<br>Cash game · INR · Banker: You</div><div class="receipt-rule"></div>${p.entries.map(([l,n])=>`<div class="receipt-row"><span>${l}</span><b>${money(n)}</b></div>`).join('')}<div class="receipt-rule"></div><div class="receipt-row"><span>Total buy-ins</span><b>${money(p.buy)}</b></div><div class="receipt-row"><span>Cash-out stack</span><b>${money(p.out)}</b></div><div class="receipt-row receipt-result"><span>Poker ${net<0?'loss':'result'}</span><b class="${net<0?'negative':'positive'}">${signed(net)}</b></div><div class="receipt-rule"></div><div class="receipt-row"><span>Buy-ins received</span><b>${money(p.received)}</b></div><div class="receipt-row"><span>Payout recorded</span><b>${money(p.paid)}</b></div><div class="receipt-total ${due>0?'owed':due===0?'settled':''}"><div class="receipt-kicker">${due>0?'STILL TO PAY':due<0?'STILL TO RECEIVE':'SETTLED'}</div><strong>${money(Math.abs(due))}</strong><div class="receipt-muted">${due>0?p.name+' → Banker':due<0?'Banker → '+p.name:'No payment outstanding'}</div></div><div class="receipt-rule"></div><div class="receipt-muted" style="text-align:center">Snapshot · 6 Nov, 23:18 IST<br>Receipt C-013 · revision 4<br>Record only · no money transferred</div></section><div class="actions">${button(icon('receipt')+'Share receipt','share-receipt','primary')}${button(icon('download')+'Save receipt','save-receipt')}</div><p class="hint">Only this player’s details and relevant payments. Photos and phone numbers stay private.</p>`}
function settings(){return head('Settings','Your preferences. Your records.','home')+`<div class="list-row"><div class="grow"><strong>Dark appearance</strong><small>Choose your preferred look</small></div><button class="toggle" data-action="theme" role="switch" aria-checked="${document.documentElement.dataset.theme==='dark'}" aria-label="Dark appearance"></button></div><div class="section-head"><h2>Save & recovery</h2></div>${notice('Keep an independent backup. Browser data can be cleared or lost.','warn')}<div class="stack">${link('Cloud backup','cloud')}${button('Export full backup','export-backup')}${link('Restore full backup','restore')}${button('Export transaction CSV','export-csv')}${link('Install Cash Out','install')}</div><div class="section-head"><h2>Privacy</h2></div>${link('Privacy & recovery','privacy','w-full')}`}
function cloud(){return head('Cloud backup','Keep a recoverable copy of your records.','settings')+`<section class="card">${detail('Provider','Google Drive')}${detail('Connection','Not connected')}${detail('Last cloud backup','Not yet')}</section>${notice('Cash Out requests access only to its own hidden app-data folder, not the rest of your Drive.')}<div class="actions">${button('Connect Google Drive','connect-google','primary')}</div><div class="section-head"><h2>iCloud Drive</h2></div><p class="small">Export a full backup, then save it to iCloud Drive through Files. Automatic iCloud backup is not connected.</p><div class="actions">${button('Export full backup','export-backup')}</div>${notice('CSV is for analysis. A full backup is needed to restore players, photos, tables, payments and activity.')}`}
function restore(){return head('Restore full backup','Preview before replacing your records.','settings')+`<form data-form="restore"><div class="field"><label for="restore-file">Cash Out backup · JSON</label><input id="restore-file" type="file" accept="application/json,.json" required></div>${notice('The file is checked before restoration. Current records stay untouched until you confirm replacement.')}<div class="actions"><button class="button primary" type="submit">Check backup file</button></div></form>`}
function restoreReview(){return head('Restore this backup?','Check the contents before continuing.','restore')+`<section class="card">${detail('Backup date','12 Nov 2026, 23:18 IST')}${detail('Players','15')}${detail('Completed tables','10')}${detail('Current table','Friday Night')}${detail('Audit entries','186')}${detail('Photos and payments','Included')}</section>${notice('This replaces the records on this device. Export a full backup of the current workspace first.','warn')}<form data-form="restore-confirm"><label class="check"><input type="checkbox" required> I have kept a backup of my current records.</label><div class="actions"><button class="button primary" type="submit">Restore backup</button>${link('Keep current records','settings')}</div></form>`}
function install(){return head('Install Cash Out','Keep the app within reach.','settings')+`<section class="card"><h2>iPhone / iPad</h2><div class="timeline" style="margin-top:20px">${['Open Cash Out in Safari.','Open Share, then Add to Home Screen.','Confirm the name, then tap Add.'].map((t,i)=>`<div class="timeline-item"><strong>${i+1}.</strong> ${t}</div>`).join('')}</div></section><section class="card" style="margin-top:16px"><h2>Android</h2><p class="small" style="margin-top:12px">Open the browser menu, then choose Install app or Add to Home screen.</p></section>${notice('Open online once to prepare offline files. Installation is separate from backing up your data.')}<div class="actions">${button('Check offline readiness','check-offline')}</div>`}
function privacy(){return head('Privacy & recovery','You control what leaves your device.','settings')+`<div class="stack"><section class="card"><h3>Private records</h3><p class="small" style="margin-top:10px">Player contact details, photos and table records stay private. Shared receipts contain only the selected player’s results and relevant payments.</p></section><section class="card"><h3>Device storage</h3><p class="small" style="margin-top:10px">Clearing site data or losing this device can remove local records. Keep a full backup somewhere independent.</p></section><section class="card"><h3>Files and cloud</h3><p class="small" style="margin-top:10px">Full backups and CSV exports contain private information. Store and share them carefully. A downloaded file is not a confirmed recoverable backup until you check it.</p></section></div><div class="actions">${link('Backup settings','cloud','primary')}${button('Check storage protection','protect-storage')}</div>`}
let tournamentRunning=false,tournamentDeadline=0,tournamentSeconds=1122,tournamentLevel=4,tournamentEliminated=false,tournamentStarted=false;
function tournamentTabs(selected){return `<nav class="segment" aria-label="Tournament pages">${[['tournament-setup','Setup'],['tournament','Live'],['tournament-payouts','Payouts']].map(([r,l])=>`<a href="#${r}" class="${selected===r?'selected':''}" ${selected===r?'aria-current="page"':''}>${l}</a>`).join('')}</nav>`}
function tournamentSetup(){return head('Start tournament','One table. Clear rules from the first hand.','home')+`<form data-form="tournament-setup"><div class="field"><label for="tournament-name">Tournament name</label><input id="tournament-name" value="Friday Cup" maxlength="60" required></div><div class="two"><div class="field"><label for="starting-stack">Starting chips</label><input id="starting-stack" type="number" min="1" value="20000" required></div><div class="field"><label for="tournament-buy">Entry · ₹</label><input id="tournament-buy" inputmode="decimal" value="1500" required></div></div><div class="two"><div class="field"><label for="level-length">Level · minutes</label><input id="level-length" type="number" min="1" value="20" required></div><div class="field"><label for="seats">Seats</label><input id="seats" type="number" min="2" max="10" value="9" required></div></div><div class="field"><label for="registration-level">Registration closes after</label><select id="registration-level"><option>Level 4</option><option>Level 3</option><option>Before play starts</option></select></div><div class="list-row"><div class="grow"><strong>Rebuys</strong><small>₹1,000 · until level 4 ends</small></div><input type="checkbox" aria-label="Allow rebuys" checked></div><div class="list-row"><div class="grow"><strong>Add-on</strong><small>₹500 · one per player</small></div><input type="checkbox" aria-label="Allow add-on" checked></div>${link('Review blind & break structure','tournament-structure','text w-full')}${notice('Tournament chips have no cash exchange value. Entry money, fees, prizes and actual payments are recorded separately.')}<div class="actions"><button class="button primary" type="submit">Review tournament</button></div></form>`}
function structure(){return head('Blind structure','20-minute levels · big blind ante','tournament-setup')+`<section class="card">${[['1','25 / 50','—'],['2','50 / 100','100'],['3','75 / 150','150'],['4','100 / 200','200'],['Break','10 minutes',''],['5','150 / 300','300'],['6','200 / 400','400'],['7','300 / 600','600']].map(([l,b,a])=>detail(l==='Break'?'Break':'Level '+l,`${b}${a?' · ante '+a:''}`)).join('')}</section>${notice('Late registration and rebuys close after level 4. Review all levels, break times and the heads-up ante policy before starting.')}<div class="actions">${link('Back to setup','tournament-setup','primary')}</div>`}
function tournament(){const seconds=tournamentRunning?Math.max(0,Math.ceil((tournamentDeadline-Date.now())/1000)):tournamentSeconds;return head('Friday Cup','One table · 9 players','home')+tournamentTabs('tournament')+`<section class="clock-panel"><span class="eyebrow" id="level-label">Level ${tournamentLevel} · ${tournamentRunning?'running':'paused'}</span><div class="clock-number" id="tournament-clock">${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}</div><strong style="font-size:24px">${tournamentLevel===4?'100 / 200':'150 / 300'} <small>chips</small></strong><p class="small">Big blind ante · ${tournamentLevel===4?'200':'300'} chips</p><div class="context-rule"></div><small>Next: ${tournamentLevel===4?'150 / 300 · 300 ante':'200 / 400 · 400 ante'}</small></section><div class="two" style="margin-top:14px">${button(tournamentRunning?'Pause clock':'Resume clock','tournament-pause')}${button('Next level','tournament-next')}</div><div class="section-head"><h2>${tournamentEliminated?'6':'7'} remaining</h2>${link('Entrants & seats','tournament-players','text compact')}</div><section class="card">${detail('Prize pool','₹15,000')}${detail('Paid places','3')}${detail('Registration','Open until level 4 ends')}</section><div class="actions">${link('Add entry / rebuy','tournament-entry')}${link('Record elimination','tournament-elimination')}${link('Review prizes','tournament-payouts')}</div>`}
function tournamentPlayers(){return head('Entrants & seats','Friday Cup · 9 players','tournament')+contacts.slice(0,9).map((p,i)=>`<div class="list-row"><span class="tag">${i+1}</span>${identity(p,i===2&&tournamentEliminated?'Finished 7th':i>6?'Eliminated':'Playing')}<span class="small ${i>6?'muted':'positive'}">${i>6?'Out':'Entry paid'}</span></div>`).join('')+`<div class="actions">${link('Add entry / rebuy','tournament-entry','primary')}</div>`}
function tournamentEntry(){return head('Tournament entry','Cash and chips are separate.','tournament')+`<form data-form="tournament-entry"><div class="field"><label for="entrant">Player</label><select id="entrant">${contacts.slice(0,9).map(p=>`<option>${p.name}</option>`).join('')}</select></div><div class="field"><label for="entry-type">Entry type</label><select id="entry-type"><option value="rebuy">Rebuy · ₹1,000 · 20,000 chips</option><option value="initial">Initial entry · ₹1,500 · 20,000 chips</option><option value="addon">Add-on · ₹500 · 10,000 chips</option></select></div>${notice('Allowed until level 4 ends. A rebuy/add-on changes the prize pool and is retained in the tournament ledger.')}<fieldset class="field"><legend>Entry payment</legend><label class="check"><input type="radio" name="entry-received" value="yes" required> Received now</label><label class="check"><input type="radio" name="entry-received" value="no"> Not yet · track as due</label></fieldset><div class="actions"><button class="button primary" type="submit">Review entry</button></div></form>`}
function elimination(){return head('Record elimination','Finish order stays traceable.','tournament')+`<form data-form="elimination"><div class="field"><label for="eliminated-player">Player</label><select id="eliminated-player">${contacts.slice(0,7).map(p=>`<option ${p.id===3?'selected':''}>${p.name}</option>`).join('')}</select></div><section class="card" style="margin-top:20px">${detail('Finish position','7th')}${detail('Prize','₹0')}${detail('Players remaining after','6')}</section>${notice('Check simultaneous eliminations and finish order before confirming. Recording a place never marks a prize as paid.')}<label class="check"><input type="checkbox" required> I checked the player and finishing position.</label><div class="actions"><button class="button primary" type="submit">Confirm elimination</button>${link('Keep player in','tournament')}</div></form>`}
function prizePool(){return head('Prize pool & payouts','Friday Cup','tournament')+tournamentTabs('tournament-payouts')+hero('Cash prize pool','₹15,000')+`<section class="card" style="margin-top:16px">${detail('9 entries × ₹1,500','₹13,500')}${detail('2 rebuys × ₹1,000','₹2,000')}${detail('1 add-on × ₹500','₹500')}${detail('Disclosed fees','−₹1,000')}</section><div class="section-head"><h2>Payout structure</h2><span class="tag good">100%</span></div><section class="card">${detail('1st · 50%','₹7,500')}${detail('2nd · 30%','₹4,500')}${detail('3rd · 20%','₹3,000')}${detail('Total','₹15,000','total')}</section>${notice('Entries and prizes must reconcile exactly. Unpaid entries remain visible; promised contributions are not money held.')}<div class="actions">${link('Final standings','tournament-results','primary')}${button('Edit payout structure','edit-prizes')}</div>`}
function tournamentResults(){return head('Final standings','Friday Cup · completed tournament','history')+hero('Prize pool','₹15,000')+`<div class="section-head"><h2>Paid places</h2></div>${[['1','Jamie Chen','₹7,500'],['2','Alex Morgan','₹4,500'],['3','Taylor Reed','₹3,000']].map(([rank,name,prize])=>`<section class="card" style="margin-top:10px"><div class="row"><div><span class="tag">${rank}${rank==='1'?'st':rank==='2'?'nd':'rd'}</span><h3 style="margin-top:10px">${name}</h3></div><strong>${prize}</strong></div><small>Prize not recorded paid</small></section>`).join('')}<div class="actions">${button('Review prize payments','tournament-prize-payment','primary')}${button('Share results','share-tournament')}</div>${notice('A finishing position and a paid prize are separate records. Cash-game call-time rules do not apply to tournament elimination.')}`}
function components(){return head('Component library','Shared product components and interaction states.','home')+`<section class="component-section"><span class="eyebrow">01 / Identity & surfaces</span><div class="profile-result magic-card" style="margin-top:14px"><span class="eyebrow">Net poker result</span><div class="amount positive">+₹12,400</div><p class="small">Magic UI surface · exact values stay still</p></div>${identity(contacts[1],'Saved player · stable identity')}</section><section class="component-section"><span class="eyebrow">02 / Statistics</span><div class="two stats-grid" style="margin-top:14px">${statCard('Average win','+₹4,800','6 winning sessions','positive')}${statCard('Average loss','−₹4,100','4 losing sessions','negative')}</div></section><section class="component-section"><span class="eyebrow">03 / Navigation & data</span>${profileTabs('Component profile tabs')}${profileTab==='overview'?profileTrend():profileSessionRows()}</section><section class="component-section"><span class="eyebrow">04 / Financial controls</span><div class="stack" style="margin-top:14px">${link('Primary action','home','primary')}${link('Secondary action','home')}${link('Destructive review','early-exit','danger')}<button class="button" disabled>Unavailable action</button></div>${playerCard(players[0])}</section><section class="component-section"><span class="eyebrow">05 / Feedback & recovery</span>${notice('Saved on this device. Cloud backup is a separate status.','good')}${notice('Check the amount before recording.','warn')}${notice('Unable to save. Keep your entry open.','error')}<button class="button primary w-full" data-action="component-save">Update preference</button><p class="small" style="margin-top:10px">Spectrum action feedback follows completion. Exact money and touch targets do not morph.</p></section><section class="component-section"><span class="eyebrow">06 / Receipts & dialogs</span><div class="stack" style="margin-top:14px">${link('Player receipt · receive / pay / settled','receipt')}${link('Early profitable exit warning','early-exit')}${link('Table settings','table-settings')}</div></section>`}
const pages={home,'new-table':newTable,table,'table-settings':tableSettings,players:()=>roster(false),'add-player':()=>roster(true),'new-player':playerForm,player:profile,'buy-in':amountPage,'amount-review':amountReview,'cash-out':cashout,'cash-out-review':()=>cashReview(false),'early-exit':()=>cashReview(true),correction:()=>{amountDraft.kind='correction';if(!players.some(p=>p.id===amountDraft.id))amountDraft.id=players[0].id;if(!amountDraft.amount)amountDraft.amount=String(players[0].buy);return amountPage()},review,activity,history:historyPage,'history-detail':historyDetail,insights,settlement,payment,payments:paymentsPage,receipt,settings,cloud,restore,'restore-review':restoreReview,install,privacy,'tournament-setup':tournamentSetup,'tournament-structure':structure,tournament,'tournament-players':tournamentPlayers,'tournament-entry':tournamentEntry,'tournament-elimination':elimination,'tournament-payouts':prizePool,'tournament-results':tournamentResults,components};
function render(){activeInfo=false;$('#toast').textContent='';currentRoute=location.hash.slice(1)||'home';if(!pages[currentRoute])currentRoute='home';if(currentRoute==='early-exit'&&cashDraft.amount==='')cashDraft.amount='7000';const meta=routeMeta.find(r=>r.id===currentRoute);$('#screen').innerHTML=pages[currentRoute]();if(currentRoute==='early-exit'&&$('#early-exit-dialog')?.showModal){$('#early-exit-dialog').showModal();$('#early-exit-dialog').addEventListener('cancel',e=>{e.preventDefault();go('cash-out')})}$('#screen-name').textContent=meta?.label||'Home';$('#screen-context').textContent=contexts[currentRoute]||'A production-facing screen with the same components, navigation and confirmation rules as the rest of Cash Out.';$('#routes').innerHTML=Object.entries(groups).map(([group,rs])=>`<div class="map-group">${group}</div>${rs.map(([r,l])=>`<a href="#${r}" class="map-link ${r===currentRoute?'current':''}" ${r===currentRoute?'aria-current="page"':''}>${l}</a>`).join('')}`).join('');$('#page-count').textContent=routeMeta.length;const selected=currentRoute.startsWith('tournament')||['home','new-table','table','table-settings','add-player','buy-in','amount-review','cash-out','cash-out-review','early-exit','correction','review','activity','settlement','payment','payments','receipt'].includes(currentRoute)?'home':['players','player','new-player'].includes(currentRoute)?'players':currentRoute.startsWith('history')?'history':currentRoute==='insights'?'insights':'';$('#navigation').innerHTML=`<div class="nav">${[['home','table','Tables'],['players','players','Players'],['history','history','History'],['insights','chart','Insights']].map(([r,i,l])=>`<a href="#${r}" class="${r===selected?'active':''}" ${r===selected?'aria-current="page"':''}>${icon(i)}${l}</a>`).join('')}</div>`;$('#settings-link').innerHTML=icon('settings');window.CashMotionLibrary?.mount($('#screen'));$('#page-map').classList.remove('open');$('#map-control').setAttribute('aria-expanded','false')}
function theme(){const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';$('#theme-control').textContent=dark?'Light theme':'Dark theme';$('#theme-control').setAttribute('aria-label',dark?'Switch to light theme':'Switch to dark theme');if(currentRoute==='settings')render()}
function amountValue(value){return /^\d{1,9}(?:\.\d{0,2})?$/.test(value)&&Number.isFinite(Number(value))?Number(value):null}
function info(title,text,back=currentRoute){activeInfo=true;$('#screen').innerHTML=head(title,'',back)+notice(text);$('#screen').focus({preventScroll:true})}
let activeTransferAmount=6200;
document.addEventListener('click',async e=>{const anchor=e.target.closest('a[href^="#"]');if(activeInfo&&anchor?.getAttribute('href')===location.hash){e.preventDefault();render();return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=Number(b.dataset.id);switch(a){
case'theme':theme();break;case'profile-tab':profileTab=b.dataset.value;render();document.querySelector('.profile-segment .selected')?.focus({preventScroll:true});break;case'filter':filter=b.dataset.value;render();break;
case'profile':profileId=id;go('player');break;case'edit-player':editPlayerId=id;go('new-player');break;
case'seat':if(players.some(p=>p.id===id)){toast('Already seated at this table.');break}amountDraft={kind:'buy',id,amount:'',received:'',reason:''};go('buy-in');break;
case'rebuy':case'reentry':amountDraft={kind:a,id,amount:'',received:'',reason:''};go('buy-in');break;
case'cashout':cashDraft={id,amount:players.find(p=>p.id===id)?.out===null?'':String(players.find(p=>p.id===id)?.out||0),override:false};go('cash-out');break;
case'player-payments':go('payment');break;
case'player-options':amountDraft={kind:'correction',id,amount:String(players.find(p=>p.id===id)?.buy||0),received:'',reason:''};go('correction');break;
case'archive':if(!b.dataset.confirm){b.dataset.confirm='yes';b.textContent='Confirm archive · history kept'}else{contacts.find(p=>p.id===id).archived=true;go('players')}break;
case'shortcut':{const n=(Number($('#amount')?.value)||0)+Number(b.dataset.value);if($('#amount')){$('#amount').value=String(n);amountDraft.amount=String(n)}break}
case'clear':if($('#amount')){$('#amount').value='';amountDraft.amount=''}break;
case'key':{const input=$('#amount')||$('#cash-stack');if(!input)break;const v=b.dataset.value,next=v==='⌫'?input.value.slice(0,-1):input.value+v;if(/^\d{0,9}(?:\.\d{0,2})?$/.test(next)){input.value=next;input.dispatchEvent(new Event('input',{bubbles:true}))}break}
case'confirm-amount':{const n=Number(amountDraft.amount)||2000;let p=players.find(p=>p.id===amountDraft.id);if(!p){p={...contacts.find(p=>p.id===amountDraft.id),buy:0,out:null,received:0,firstBuy:Date.now(),minimum:minimumHours*3600000};players.push(p)}if(amountDraft.kind==='correction')p.buy=n;else{if(amountDraft.kind==='reentry'){p.priorOut=p.out||0;p.out=null}p.buy+=n;if(amountDraft.received==='yes')p.received+=n}p.last=n;tx.unshift({name:p.name,title:amountDraft.kind==='correction'?'Buy-in corrected':'Buy-in recorded',amount:n,time:'Now'});amountDraft.amount='';go('table');break}
case'allow-early':await window.CashMotionLibrary?.closeModal($('#early-exit-dialog'));cashDraft.override=true;go('cash-out-review');break;
case'confirm-cashout':{const p=person();p.out=(p.priorOut||0)+(Number(cashDraft.amount)||0);tx.unshift({name:p.name,title:cashDraft.override?'Cash-out · early-exit house exception':'Cash-out recorded',amount:p.out,time:'Now'});go('table');toast('Stack recorded · payout remains separate.',true);break}
case'close-table':if(!balance().pending.length&&balance().difference===0){tableClosed=true;go('settlement')}break;
case'rake':info('Add rake','Enter each rake addition as cash, review the resulting total, then confirm. Rake remains separate from player statistics.','table');break;
case'bank-mode':case'direct-mode':{const seg=b.closest('.segment');seg.querySelectorAll('button').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});window.CashMotionLibrary?.moveSegment(seg);toast(a==='direct-mode'?'One outstanding recipient: the banker payout remains ₹6,200.':'Settlement routes through the banker.');break}
case'share-receipt':info('Share player receipt','Review the player’s receipt, then choose a person or destination in your device’s share sheet. No phone number or photo is included.','receipt');break;
case'save-receipt':window.print();break;
case'share-summary':info('Share table summary','Friday Regulars · buy-ins ₹90,000 · cash-outs ₹88,200 · rake ₹1,800. Remaining: Banker → Jamie Chen ₹6,200. Names and amounts only.','settlement');break;
case'connect-google':info('Connect Google Drive','Continue with your Google account to back up Cash Out records to its own app-data folder. Live authorization will be available after the production app is configured.','cloud');break;
case'export-backup':case'export-csv':info(a==='export-backup'?'Export full backup':'Export transactions',a==='export-backup'?'Save the full backup to Files or your chosen drive. Check that the file exists before marking it as safely stored.':'The private CSV includes table details and auditable transactions. Share player receipts when you only want someone’s individual result.','settings');break;
case'check-offline':case'protect-storage':info('Device readiness','Offline files and storage protection must be checked on the installed app. Keep a separate full backup even when browser storage is protected.','install');break;
case'csv-import':info('Import transaction CSV','Choose a Cash Out CSV. Validate its schema, exact amounts and duplicate transaction IDs before generating insights. Existing ledger records remain unchanged.','insights');break;
case'tournament-pause':if(tournamentRunning){tournamentSeconds=Math.max(0,Math.ceil((tournamentDeadline-Date.now())/1000));tournamentRunning=false}else{tournamentDeadline=Date.now()+tournamentSeconds*1000;tournamentRunning=true}render();break;
case'tournament-next':if(!b.dataset.confirm){b.dataset.confirm='yes';b.textContent='Confirm advance';toast('Advance early? Remaining level time will be discarded.')}else{tournamentRunning=false;tournamentSeconds=1200;tournamentLevel=5;render()}break;
case'tournament-prize-payment':info('Review prize payments','Jamie Chen: ₹7,500 · Alex Morgan: ₹4,500 · Taylor Reed: ₹3,000. Record each prize as paid only after the money changes hands.','tournament-results');break;
case'edit-prizes':info('Edit payout structure','Three places: 50% / 30% / 20%. Total must be exactly 100%, with paise rounding allocated explicitly. Locked structures require an audited correction.','tournament-payouts');break;
case'share-tournament':info('Share tournament results','Friday Cup · 1st Jamie Chen ₹7,500 · 2nd Alex Morgan ₹4,500 · 3rd Taylor Reed ₹3,000. Payment status is shown separately.','tournament-results');break;
case'component-save':window.CashMotionLibrary?.runButton(b,async()=>undefined,{successLabel:'Preference updated'});break;case'component-danger':toast('Destructive actions require confirmation and preserve financial history.');break;
}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='session-inspector'){profileSession=Number(t.value);const holder=document.createElement('div');holder.innerHTML=profileTrend();const chart=t.closest('.profile-trend');chart.querySelector('.chart').outerHTML=holder.querySelector('.chart').outerHTML;chart.querySelector('#session-readout').innerHTML=holder.querySelector('#session-readout').innerHTML;t.setAttribute('aria-valuetext',holder.querySelector('#session-inspector').getAttribute('aria-valuetext'))}if(t.id==='player-search')$('#roster-results').innerHTML=rosterRows(t.value,currentRoute==='add-player');if(['amount','cash-stack','payment-amount'].includes(t.id)){const old=t.dataset.valid||'';if(!/^\d{0,9}(?:\.\d{0,2})?$/.test(t.value)){t.value=old;toast('Use numbers and up to two decimal places.')}else t.dataset.valid=t.value;if(t.id==='amount')amountDraft.amount=t.value;if(t.id==='cash-stack')cashDraft.amount=t.value}});
document.addEventListener('change',e=>{if(e.target.id==='receipt-player'){receiptId=e.target.value;render()}});
document.addEventListener('submit',e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();switch(form.dataset.form){
case'new-table':if(!tableClosed&&players.length){toast('Close and balance the current table first.');break}tableName=$('#table-name').value.trim();minimumHours=Number($('#minimum-new').value);players=[];go('table');break;
case'table-settings':if(Number($('#big-blind').value)<Number($('#small-blind').value)){toast('Big blind must be at least the small blind.');break}minimumHours=Number($('#minimum-hours').value);window.CashMotionLibrary?.runButton(form.querySelector('[type=submit]'),async()=>undefined,{successLabel:'Settings updated'});break;
case'player':{const name=$('#player-name').value.trim();if(!name)break;if(contacts.some(p=>p.id!==editPlayerId&&p.name.toLowerCase()===name.toLowerCase())){toast('A player with this name already exists. Check saved players.');break}if(editPlayerId){const p=contacts.find(p=>p.id===editPlayerId);Object.assign(p,{name,phone:$('#player-phone').value});const seated=players.find(p=>p.id===editPlayerId);if(seated)seated.name=name;editPlayerId=null}else contacts.push({id:Math.max(...contacts.map(p=>p.id))+1,name,phone:$('#player-phone').value,last:5000});go('players');break}
case'amount':{const n=amountValue($('#amount').value);if(n===null||n<=0){$('#amount-error').textContent='Enter an amount greater than zero using up to two decimal places.';break}amountDraft.amount=$('#amount').value;amountDraft.received=form.querySelector('[name=received]:checked')?.value||'';amountDraft.reason=$('#reason')?.value.trim()||'';go('amount-review');break}
case'cashout':{const n=amountValue($('#cash-stack').value);if(n===null){$('#cash-error').textContent='Enter a valid stack. Zero is allowed.';break}cashDraft.amount=$('#cash-stack').value;const p=person();go(n+(p.priorOut||0)>p.buy&&!clockFor(p).met?'early-exit':'cash-out-review');break}
case'payment':{const n=amountValue($('#payment-amount').value);if(n===null||n<=0||n>activeTransferAmount){toast('Enter a positive amount no greater than the remaining payment.');break}activeTransferAmount-=n;transferPaid=activeTransferAmount===0;receiptPlayers.jamie.paid+=n;go('settlement');toast('Payment recorded.',true);break}
case'reverse':info('Confirm record reversal','Reverse the ₹5,000 payment record? Reason: '+$('#reverse-reason').value.trim()+'. The original record stays in history; no money moves.','payments');break;
case'restore':if($('#restore-file').files.length)go('restore-review');break;
case'restore-confirm':restored=true;go('home');toast('Backup restored.');break;
case'tournament-setup':info('Confirm tournament rules','Friday Cup · 9 seats · 20,000 starting chips · ₹1,500 entry · 20-minute levels · registration and rebuys close after level 4. Review structure and payouts before starting.','tournament');break;
case'tournament-entry':info('Confirm tournament entry',$('#entrant').value+' · '+$('#entry-type').selectedOptions[0].text+'. Payment: '+(form.querySelector('[name=entry-received]:checked')?.value==='yes'?'received':'not yet received')+'. Review before recording.','tournament');break;
case'elimination':tournamentEliminated=true;go('tournament');toast('Finish position recorded. Prize payment stays separate.');break;
}});
$('#theme-control').onclick=theme;$('#map-control').onclick=()=>{const open=$('#page-map').classList.toggle('open');$('#map-control').setAttribute('aria-expanded',String(open))};
window.addEventListener('hashchange',()=>{render();$('#screen').focus({preventScroll:true});if(innerWidth<=760)window.scrollTo({top:0,behavior:'instant'})});
setInterval(()=>{document.querySelectorAll('[data-clock]').forEach(el=>{const p=players.find(p=>p.id===Number(el.dataset.clock));if(!p)return;const c=clockFor(p);el.classList.toggle('met',c.met);if(el.querySelector('strong').textContent!==c.text)el.querySelector('strong').textContent=c.text;el.querySelector('small').textContent=c.met?'Eligible to leave':'Call time pending'});if(currentRoute==='tournament'&&tournamentRunning){const sec=Math.max(0,Math.ceil((tournamentDeadline-Date.now())/1000));if($('#tournament-clock'))$('#tournament-clock').textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');if(sec===0){tournamentRunning=false;tournamentSeconds=0;render()}}},1000);
render();
